const item = $input.first();
const msg = item.json.message || {};
const from = msg.from || {};
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) {
  return [{ json: { ok: false, chatId: msg.chat && msg.chat.id, error: 'No image binary on message (send as photo or image file)' } }];
}
const meta = item.binary[binaryKey];
const buf = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const mime = meta.mimeType || (msg.document && msg.document.mime_type) || 'image/jpeg';
if (!String(mime).startsWith('image/')) {
  return [{ json: { ok: false, chatId: msg.chat && msg.chat.id, error: 'File is not an image' } }];
}
const dataUrl = `data:${mime};base64,${buf.toString('base64')}`;
const recordId = 'exp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
const capturedAt = new Date().toISOString();
const displayName = (() => {
  const username = String(from.username || '').trim();
  if (username) return '@' + username.replace(/^@/, '');
  const first = String(from.first_name || '').trim();
  const last = String(from.last_name || '').trim();
  const full = [first, last].filter(Boolean).join(' ');
  if (full) return full;
  if (from.id !== undefined && from.id !== null && String(from.id).trim()) return String(from.id);
  return 'unknown';
})();
const telegramUser = displayName;
const chatId = msg.chat && msg.chat.id;

const extractPrompt = `Extract expense fields from this receipt image. Return ONLY valid JSON (no markdown) with keys:\n{\n  \"date\": \"YYYY-MM-DD or empty string\",\n  \"vendor\": \"merchant name\",\n  \"amount\": \"total as number string\",\n  \"currency\": \"ISO code e.g. EUR\",\n  \"tax\": \"tax/VAT if visible else empty\",\n  \"category\": \"meals|travel|supplies|other\",\n  \"notes\": \"short gist of line items\"\n}\nIf this is not a usable receipt, return {\"error\":\"unusable\"}.`;

return [{
  json: {
    ok: true,
    recordId,
    capturedAt,
    telegramDisplayName: displayName,
    telegramUserId: String(from.id || ''),
    telegramUser,
    chatId,
    telegramChatId: chatId,
    extractPrompt,
    dataUrl,
    mime
  },
  binary: item.binary
}];

const prep = $('Prep Image + Meta').first().json;
const raw = $input.first().json;
if (raw.error || raw.message === 'No endpoints found' || (raw.error && raw.error.message)) {
  const msg = (raw.error && (raw.error.message || raw.error.description)) || raw.description || raw.message || 'OpenRouter request failed';
  return [{ json: { ok: false, chatId: prep.chatId, error: String(msg) } }];
}
const content = (((raw.choices || [])[0] || {}).message || {}).content || '';
let text = typeof content === 'string' ? content : JSON.stringify(content);
text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { ok: false, chatId: prep.chatId, error: 'Could not parse model JSON', raw: text.slice(0, 500) } }];
}
if (parsed.error || (!parsed.vendor && !parsed.amount)) {
  return [{ json: { ok: false, chatId: prep.chatId, error: 'Photo does not look like a usable receipt', raw: parsed } }];
}
return [{
  json: {
    ok: true,
    recordId: prep.recordId,
    date: parsed.date || '',
    vendor: parsed.vendor || '',
    amount: parsed.amount || '',
    currency: parsed.currency || '',
    tax: parsed.tax || '',
    category: parsed.category || '',
    notes: parsed.notes || '',
    status: 'pending approval',
    capturedAt: prep.capturedAt,
    telegramDisplayName: prep.telegramDisplayName,
    telegramUserId: prep.telegramUserId,
    telegramUser: prep.telegramUser,
    chatId: prep.chatId,
    telegramChatId: prep.telegramChatId
  }
}];

