const cq = $json.callback_query || {};
const from = cq.from || {};
const msg = cq.message || {};
const chatId = (msg.chat && msg.chat.id) || (from && from.id);
const queryId = cq.id;
const messageId = msg.message_id;
const originalText = msg.text || '';
const raw = String(cq.data || '');
const parts = raw.split(':');
const action = (parts[0] || '').toLowerCase();
const recordId = parts.slice(1).join(':');
if (String(from.id) !== '7813999484') {
  return [{ json: { ok: false, chatId, queryId, messageId, error: 'Unauthorized approver' } }];
}
if (!recordId || (action !== 'approve' && action !== 'reject')) {
  return [{ json: { ok: false, chatId, queryId, messageId, error: 'Unknown approval action' } }];
}
return [{ json: { ok: true, approved: action === 'approve', recordId, chatId, queryId, messageId, originalText } }];

