function decisionLinkUrl(recordId, decision) {
  const qs = 'recordId=' + encodeURIComponent(String(recordId))
    + '&decision=' + encodeURIComponent(String(decision));
  return publicBaseUrl + 'webhook/expense-chat-link?' + qs;
}

function buildPendingExpenseCard({ recordId, vendor, amount, currency, date, category, notes, telegramDisplayName }) {
  return {
    cardsV2: [
