const raw = $input.first().json || {};
const body = (raw && typeof raw.body === 'object' && raw.body !== null && !Array.isArray(raw.body))
  ? raw.body
  : raw;

// Workspace add-on events nest under `chat`; classic Chat apps use top-level type/eventType.
const chat = (body.chat && typeof body.chat === 'object') ? body.chat : null;
const isAddon = Boolean(chat);
const messagePayload = chat?.messagePayload || null;
const addedPayload = chat?.addedToSpacePayload || null;
const cardPayload = chat?.buttonClickedPayload || chat?.cardClickedPayload || null;

const classicType = String(body.type || body.eventType || '').trim();
const spaceName = String(
  messagePayload?.space?.name
  || addedPayload?.space?.name
  || cardPayload?.space?.name
  || body.space?.name
  || ''
).trim();

function paramsToObject(parameters = []) {
  const out = {};
  for (const p of parameters) {
    if (p && p.key !== undefined) out[p.key] = p.value;
  }
  return out;
}

function parseClassicCardClick(event = {}) {
  const type = String(event.type || event.eventType || '');
  if (type !== 'CARD_CLICKED') return { ok: false, error: 'not_card_clicked' };
  const action = event.action || {};
  const actionNames = [
    action.actionMethodName,
    event.common?.invokedFunction,
    action.function,
  ];
  if (!actionNames.includes('expense_decide')) return { ok: false, error: 'unknown_action' };
  const params = paramsToObject(action.parameters || []);
  const recordId = String(params.recordId || '').trim();
  const decision = String(params.decision || '').toLowerCase();
  if (!recordId || (decision !== 'approve' && decision !== 'reject')) {
    return { ok: false, error: 'invalid_params' };
  }
  return { ok: true, recordId, approved: decision === 'approve' };
}

function parseAddonCardClick(payload = {}) {
  const action = payload.action || payload.common?.formInputs || {};
  // Cards v2 / add-on button parameters vary; also check invokedFunction.
  const names = [
    payload.action?.actionMethodName,
    payload.common?.invokedFunction,
    payload.action?.function,
  ];
  if (!names.includes('expense_decide') && !String(payload.action?.actionMethodName || '').includes('expense_decide')) {
    // Fall through to parameters-only parse if present
  }
  const params = paramsToObject(payload.action?.parameters || []);
  if (!params.recordId && payload.common?.parameters) {
    Object.assign(params, paramsToObject(payload.common.parameters));
  }
  const recordId = String(params.recordId || '').trim();
  const decision = String(params.decision || '').toLowerCase();
  if (!recordId || (decision !== 'approve' && decision !== 'reject')) {
    return { ok: false, error: 'invalid_params' };
  }
  if (!names.includes('expense_decide') && decision) {
    // allow if params are valid expense decision
  } else if (!names.includes('expense_decide')) {
    return { ok: false, error: 'unknown_action' };
  }
  return { ok: true, recordId, approved: decision === 'approve' };
}

function spaceReadyText(name) {
  return name ? `Expense approval bot ready (${name})` : 'Expense approval bot ready';
}


function classicCardClickReply(parsed) {
  if (!parsed.ok) {
    return { actionResponse: { type: 'UPDATE_MESSAGE' }, text: 'Could not process expense decision.' };
  }
  const status = parsed.approved ? 'APPROVED' : 'REJECTED';
  const recordId = parsed.recordId;
  return {
    actionResponse: { type: 'UPDATE_MESSAGE' },
    cardsV2: [{
      cardId: `expense-${recordId}`,
      card: {
        header: { title: `Expense ${status}` },
        sections: [{
          widgets: [
            { textParagraph: { text: `<b>recordId:</b> ${recordId}` } },
            { textParagraph: { text: `<b>Status:</b> ${status}` } },
          ],
        }],
      },
    }],
  };
}

function classicReply(text, actionType) {
  if (actionType) {
    return { actionResponse: { type: actionType }, text };
  }
  return { text };
}

function addonReply(text) {
  return {
    hostAppDataAction: {
      chatDataAction: {
        createMessageAction: {
          message: { text },
        },
      },
    },
  };
}

function replyFor(text) {
  return isAddon ? addonReply(text) : classicReply(text);
}

// --- CARD / button ---
if (classicType === 'CARD_CLICKED' || cardPayload) {
  const parsed = cardPayload ? parseAddonCardClick(cardPayload) : parseClassicCardClick(body);
  return [{
    json: {
      kind: parsed.ok ? 'chat-decision' : 'invalid-card-click',
      ...parsed,
      reply: isAddon
        ? replyFor(parsed.ok ? 'Expense decision received.' : 'Could not process expense decision.')
        : classicCardClickReply(parsed),
    },
  }];
}

// --- MESSAGE / added to space ---
const isMessage = classicType === 'MESSAGE' || Boolean(messagePayload);
const isAdded = classicType === 'ADDED_TO_SPACE' || Boolean(addedPayload);
if (isMessage || isAdded) {
  return [{
    json: {
      kind: 'handshake',
      spaceId: spaceName,
      reply: replyFor(spaceReadyText(spaceName)),
    },
  }];
}

// Acknowledge unknown events in the correct envelope.
return [{
  json: {
    kind: 'ignore',
    reply: isAddon
      ? { hostAppDataAction: { chatDataAction: {} } }
      : { text: '' },
  },
}];

const decision = $input.first().json;
if (decision.kind === 'chat-link-decision' || decision.kind === 'chat-decision') {
  return [{ json: {
    source: decision.kind === 'chat-link-decision' ? 'chat-link' : 'chat',
    recordId: decision.recordId,
    approved: decision.approved,
  } }];
}
return [{ json: {
  source: 'telegram',
  recordId: decision.recordId,
  approved: decision.approved,
  chatId: decision.chatId,
  messageId: decision.messageId,
  queryId: decision.queryId,
  originalText: decision.originalText,
} }];

function shouldApplyDecision(currentStatus) {
  return String(currentStatus || '') === 'pending approval';
}

const request = $('Prepare Decision Request').first().json;
const row = $input.first().json || {};
return [{ json: { ...row, ...request, applyDecision: shouldApplyDecision(row.status) } }];

const expense = $('Gate Decision').first().json;
const statusLabel = expense.approved ? 'APPROVED' : 'REJECTED';
function widgetText(text) { return { textParagraph: { text } }; }
function buildFinalExpenseCard({ recordId, vendor, amount, currency, telegramDisplayName }, status) {
  return { cardsV2: [{ cardId: `expense-${recordId}`, card: { header: { title: `Expense ${status}`, subtitle: String(telegramDisplayName || '') }, sections: [{ widgets: [widgetText(`<b>Vendor:</b> ${vendor || ''}`), widgetText(`<b>Amount:</b> ${amount || ''} ${currency || ''}`), widgetText(`<b>recordId:</b> ${recordId || ''}`), widgetText(`<b>Status:</b> ${status}`)] }] } }] };
}
return [{ json: { chatMessageName: expense.chatMessageName, ...buildFinalExpenseCard(expense, statusLabel) } }];

const approved = $('Gate Decision').first().json.approved;
const title = approved ? 'Expense approved' : 'Expense rejected';
const replyHtml = `<!doctype html>
<html><head><meta charset="utf-8"><title>${title}</title></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;padding:2rem;max-width:32rem;margin:auto;line-height:1.4">
<h1 style="margin:0 0 .5rem">${title}</h1>
<p>The sheet and approval UIs are updating.</p>
<p style="color:#666;font-size:.9rem">You can close this tab.</p>
<script>setTimeout(() => { try { window.close(); } catch (e) {} }, 1200);</script>
</body></html>`;
return [{ json: { replyHtml } }];

const raw = $input.first().json || {};
const q = (raw.query && typeof raw.query === 'object') ? raw.query : {};
const recordId = String(q.recordId || '').trim();
const decision = String(q.decision || '').toLowerCase().trim();

function htmlPage(title, body) {
  return `<!doctype html>
<html><head><meta charset="utf-8"><title>${title}</title></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;padding:2rem;max-width:32rem;margin:auto;line-height:1.4">
<h1 style="margin:0 0 .5rem">${title}</h1>
<p>${body}</p>
<p style="color:#666;font-size:.9rem">You can close this tab.</p>
<script>setTimeout(() => { try { window.close(); } catch (e) {} }, 1200);</script>
</body></html>`;
}

if (!recordId || (decision !== 'approve' && decision !== 'reject')) {
  return [{ json: {
    kind: 'invalid-link',
    replyHtml: htmlPage('Invalid link', 'Missing recordId or decision.'),
  } }];
}

return [{ json: {
  kind: 'chat-link-decision',
  recordId,
  approved: decision === 'approve',
} }];
